static BOOL Fail(NSError **error,NSString *text){if(error)*error=[NSError errorWithDomain:@"TweakForge.Git" code:1 userInfo:@{NSLocalizedDescriptionKey:text?:@"Git 操作失败"}];return NO;}
static BOOL Check(int code,NSError **error){if(code>=0)return YES;
