 if(code==GIT_EUNBORNBRANCH)return Fail(error,@"此项目还没有本机版本。请先点击“保存本机版本”，再连接和同步远端。");
 if(code==GIT_EAUTH)return Fail(error,@"认证未通过。请检查当前仓库使用的账号、PAT 是否过期，以及令牌是否包含此仓库的 Contents 读写权限。");const git_error *e=git_error_last();NSString *message=S(e?e->message:NULL);return Fail(error,[NSString stringWithFormat:@"Git (%d)：%@",code,message.length?message:@"操作未完成"]);}
