static NSString *Safe(NSString *root,NSString *path){if(![path isKindOfClass:NSString.class]||!path.length||path.isAbsolutePath)return nil;for(NSString *part in path.pathComponents)if([part isEqual:@".git"]||[part isEqual:@".."]||[part hasPrefix:@".studio-git-"])return nil;NSString *base=root.stringByResolvingSymlinksInPath,*full=[root stringByAppendingPathComponent:path];return [full.stringByResolvingSymlinksInPath hasPrefix:[base stringByAppendingString:@"/"]]?full:nil;}
static BOOL WriteJSON(id value,NSString *path,NSError **error){NSData *d=[NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingPrettyPrinted error:error];return d&&[d writeToFile:path options:NSDataWritingAtomic error:error];}
static id ReadJSON(NSString *path){NSData *d=[NSData dataWithContentsOfFile:path];return d?[NSJSONSerialization JSONObjectWithData:d options:0 error:nil]:nil;}
static BOOL TransportURL(NSString *url,NSError **error){NSURLComponents *c=[NSURLComponents componentsWithString:url];if(c.user.length||c.password.length)return Fail(error,@"请把用户名和令牌填写在认证设置中，仓库地址不携带凭据。");if([c.scheme.lowercaseString isEqual:@"https"]&&c.host.length)return YES;
