 if([NSProcessInfo.processInfo.arguments containsObject:@"--git-test"]&&([c.scheme isEqual:@"http"]||[c.scheme isEqual:@"file"]||url.isAbsolutePath))return YES;
#endif
 return Fail(error,@"请填写 HTTPS 仓库地址，例如 https://github.com/用户/仓库.git 或 https://gitee.com/用户/仓库.git。");}
static NSString *CredentialKey(NSString *url){NSURLComponents *c=[NSURLComponents componentsWithString:url];c.user=nil;c.password=nil;c.query=nil;c.fragment=nil;NSString *path=c.path;if([path hasSuffix:@"/"])path=[path substringToIndex:path.length-1];if([path hasSuffix:@".git"])path=[path substringToIndex:path.length-4];c.path=path;c.host=c.host.lowercaseString;return c.string?:url;}
static NSDictionary *Query(NSString *url){return @{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrService:@"com.xuegao.tweakforge.git",(__bridge id)kSecAttrAccount:CredentialKey(url)};}

