static BOOL AutoPath(NSString *path){NSSet *dirs=[NSSet setWithArray:@[@".git",@".theos",@".build",@"build",@"DerivedData",@"packages",@".package-link-cache",@".StudioTrash",@"node_modules"]];for(NSString *part in path.pathComponents)if([dirs containsObject:part]||[part hasPrefix:@".studio-"]||[part hasPrefix:@"Build-"]||[part hasPrefix:@"Snapshot-"])return NO;NSString *file=path.lastPathComponent.lowercaseString;return !([@[@"o",@"deb",@"dylib",@"ipa",@"tmp",@"swp",@"p12",@"mobileprovision",@"key",@"pem"] containsObject:path.pathExtension.lowercaseString]||[file hasPrefix:@".env"]||[@[@"credentials",@"credentials.json",@".git-credentials",@".netrc",@".ds_store"] containsObject:file]);}
static NSRecursiveLock *GitLock(void){static NSRecursiveLock *lock;static dispatch_once_t once;dispatch_once(&once,^{lock=[NSRecursiveLock new];lock.name=@"Dylix Git / project transaction";});return lock;}
static NSMutableSet *BuildingRoots(void){static NSMutableSet *roots;static dispatch_once_t once;dispatch_once(&once,^{roots=[NSMutableSet new];});return roots;}
@implementation TMCGitLease
+ (instancetype)tryWrite{if(![GitLock() tryLock])return nil;return [self new];}
+ (instancetype)acquire{[GitLock() lock];return [self new];}
- (void)dealloc{[GitLock() unlock];}
+ (void)setBuilding:(BOOL)value root:(NSString *)root{@synchronized(BuildingRoots()){if(value)[BuildingRoots() addObject:root.stringByStandardizingPath];else[BuildingRoots() removeObject:root.stringByStandardizingPath];}}
+ (BOOL)hasActiveBuilds{@synchronized(BuildingRoots()){return BuildingRoots().count>0;}}
+ (BOOL)isBuilding:(NSString *)root{@synchronized(BuildingRoots()){return [BuildingRoots() containsObject:root.stringByStandardizingPath];}}
@end
static NSDictionary *ValidGitSettings(id value){
 if(![value isKindOfClass:NSDictionary.class])return @{};NSMutableDictionary *result=[NSMutableDictionary new];
 for(NSString *key in @[@"name",@"email",@"template",@"pushURL",@"pushBranch",@"authMode",@"authURL",@"account"])if([value[key] isKindOfClass:NSString.class])result[key]=value[key];
 for(NSString *key in @[@"override",@"enabled",@"afterSave",@"afterBuild",@"protect",@"delay",@"push"])if([value[key] isKindOfClass:NSNumber.class])result[key]=value[key];return result;
}
static NSString *ConsentKey(NSString *root){NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject;return [root hasPrefix:[docs stringByAppendingString:@"/"]]?[root substringFromIndex:docs.length+1]:root.stringByResolvingSymlinksInPath;}
@implementation TMCGitPreferences
+ (NSDictionary *)global{NSUserDefaults *d=NSUserDefaults.standardUserDefaults;NSMutableDictionary *s=[@{@"name":[d stringForKey:@"GitAuthor"]?:@"",@"email":[d stringForKey:@"GitEmail"]?:@"",@"enabled":@NO,@"afterSave":@YES,@"afterBuild":@YES,@"protect":@YES,@"delay":@30,@"template":@"存档 {project} · {trigger} · {date}",@"push":@NO} mutableCopy];[s addEntriesFromDictionary:ValidGitSettings([d dictionaryForKey:@"GitGlobalSettings"])];return s;}
+ (void)saveGlobal:(NSDictionary *)s{NSMutableDictionary *value=[s mutableCopy];[value removeObjectForKey:@"push"]; // Push always requires per-repository consent.
 [NSUserDefaults.standardUserDefaults setObject:value forKey:@"GitGlobalSettings"];}
+ (NSDictionary *)project:(NSString *)root{id value=ReadJSON([root stringByAppendingPathComponent:@".studio-git-settings.json"]);return ValidGitSettings(value);}
+ (BOOL)saveProject:(NSDictionary *)s root:(NSString *)root error:(NSError **)error{TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease tryWrite];if(!lease)return Fail(error,@"Git 正在处理，请稍后保存设置。");BOOL ok=WriteJSON(ValidGitSettings(s),[root stringByAppendingPathComponent:@".studio-git-settings.json"],error);if(ok&&![s[@"push"] boolValue]){NSMutableDictionary *consents=[[NSUserDefaults.standardUserDefaults dictionaryForKey:@"GitLocalPushConsents"] mutableCopy]?:[NSMutableDictionary new];[consents removeObjectForKey:ConsentKey(root)];[NSUserDefaults.standardUserDefaults setObject:consents forKey:@"GitLocalPushConsents"];}return ok;}
+ (void)confirmPushURL:(NSString *)url branch:(NSString *)branch root:(NSString *)root{NSMutableDictionary *consents=[[NSUserDefaults.standardUserDefaults dictionaryForKey:@"GitLocalPushConsents"] mutableCopy]?:[NSMutableDictionary new];consents[ConsentKey(root)]=@{@"url":url?:@"",@"branch":branch?:@""};[NSUserDefaults.standardUserDefaults setObject:consents forKey:@"GitLocalPushConsents"];}
+ (NSDictionary *)effective:(NSString *)root{NSMutableDictionary *s=[[self global] mutableCopy];NSDictionary *p=[self project:root];BOOL override=[p[@"override"] boolValue];if(override)for(NSString *key in @[@"name",@"email",@"enabled",@"afterSave",@"afterBuild",@"protect",@"delay",@"template"])if(p[key])s[key]=p[key];s[@"source"]=override?@"项目覆盖":@"全局继承";id consent=[NSUserDefaults.standardUserDefaults dictionaryForKey:@"GitLocalPushConsents"][ConsentKey(root)];BOOL confirmed=[consent isKindOfClass:NSDictionary.class]&&[consent[@"url"] isEqual:p[@"pushURL"]]&&[consent[@"branch"] isEqual:p[@"pushBranch"]];s[@"push"]=@([p[@"push"] boolValue]&&confirmed);s[@"pushURL"]=p[@"pushURL"]?:@"";s[@"pushBranch"]=p[@"pushBranch"]?:@"";return s;}
+ (NSString *)origin:(NSString *)url{NSURLComponents *c=[NSURLComponents componentsWithString:url];if(!c.host.length)return @"";return [NSString stringWithFormat:@"%@://%@%@",c.scheme.lowercaseString,c.host.lowercaseString,c.port?[NSString stringWithFormat:@":%@",c.port]:@""];}
+ (NSString *)repositoryKey:(NSString *)url{return CredentialKey(url);}
+ (NSArray *)accounts{return [NSUserDefaults.standardUserDefaults arrayForKey:@"GitAccounts"]?:@[];}
+ (NSString *)secretURL:(NSDictionary *)a{return [NSString stringWithFormat:@"%@/.tweakforge-account/%@",a[@"origin"],a[@"id"]];}
+ (BOOL)saveAccount:(NSDictionary *)account token:(NSString *)token error:(NSError **)error{NSString *origin=[self origin:account[@"origin"]];if(![origin hasPrefix:@"https://"]||![account[@"username"] length])return Fail(error,@"请填写 HTTPS 服务地址和账号。");NSMutableDictionary *a=[@{@"id":[account[@"id"] length]?account[@"id"]:NSUUID.UUID.UUIDString,@"origin":origin,@"username":account[@"username"],@"default":account[@"default"]?:@NO} mutableCopy];NSString *key=[self secretURL:a];if(!token.length&&![TMCGitService credentialForURL:key][@"token"]){return Fail(error,@"新账号需要填写 PAT。");}if(token.length&&![TMCGitService saveCredentialForURL:key username:a[@"username"] token:token error:error])return NO;
