+ (void)deleteAccount:(NSString *)identifier{NSMutableArray *list=[NSMutableArray new];for(NSDictionary *a in self.accounts)if([a[@"id"] isEqual:identifier])[TMCGitService deleteCredentialForURL:[self secretURL:a]];else[list addObject:a];[NSUserDefaults.standardUserDefaults setObject:list forKey:@"GitAccounts"];}
+ (NSDictionary *)credential:(NSString *)url root:(NSString *)root{NSDictionary *p=[self project:root];NSString *mode=p[@"authMode"]?:@"inherit";if([mode isEqual:@"none"])return @{};NSString *bound=p[@"authURL"];if(![mode isEqual:@"inherit"]&&![CredentialKey(url) isEqual:bound])return @{};
