+ (NSArray *)records:(NSString *)root{id rows=ReadJSON([root stringByAppendingPathComponent:@".studio-git-events.json"]);if(![rows isKindOfClass:NSArray.class])return @[];NSMutableArray *valid=[NSMutableArray new];for(id row in rows)if([row isKindOfClass:NSDictionary.class])[valid addObject:row];return valid;}
+ (void)record:(NSDictionary *)event root:(NSString *)root{TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease acquire];NSMutableArray *rows=[[self records:root] mutableCopy];NSMutableDictionary *row=[event mutableCopy];row[@"date"]=@(NSDate.date.timeIntervalSince1970);[rows insertObject:row atIndex:0];if(rows.count>100)[rows removeObjectsInRange:NSMakeRange(100,rows.count-100)];WriteJSON(rows,[root stringByAppendingPathComponent:@".studio-git-events.json"],nil);}
@end

