static int Credentials(git_credential **out,const char *url,const char *username,unsigned int types,void *payload){TMCGitService *service=(__bridge TMCGitService *)payload;if(service.cancelled)return GIT_EUSER;if(!(types&GIT_CREDENTIAL_USERPASS_PLAINTEXT))return GIT_PASSTHROUGH;if(service.authAttempts++>=2){git_error_set_str(GIT_ERROR_NET,"认证被拒绝，请检查用户名、PAT 权限和仓库访问权限");return GIT_EAUTH;}if(![[TMCGitPreferences origin:S(url)] isEqual:service.transportOrigin]){git_error_set_str(GIT_ERROR_NET,"认证服务地址已变化，请检查仓库 URL");return GIT_EAUTH;}NSDictionary *stored=[TMCGitPreferences credential:S(url) root:service.root];if(![stored[@"token"] length]){git_error_set_str(GIT_ERROR_NET,"请在远程设置保存仓库用户名与访问令牌 (PAT)");return GIT_EAUTH;}return git_credential_userpass_plaintext_new(out,[stored[@"username"] UTF8String],[stored[@"token"] UTF8String]);}
static int Transfer(const git_indexer_progress *stats,void *payload){TMCGitService *s=(__bridge TMCGitService *)payload;if(s.cancelled)return GIT_EUSER;NSTimeInterval now=NSDate.timeIntervalSinceReferenceDate;if(s.progress&&(now-s.lastProgress>.1||stats->received_objects==stats->total_objects)){s.lastProgress=now;s.progress([NSString stringWithFormat:@"接收对象 %u / %u · %.1f MB",stats->received_objects,stats->total_objects,stats->received_bytes/1048576.0],stats->total_objects?(double)stats->received_objects/stats->total_objects:0);}return 0;}
static int Sideband(const char *text,int length,void *payload){TMCGitService *s=(__bridge TMCGitService *)payload;return s.cancelled?GIT_EUSER:0;}
static int PushTransfer(unsigned int current,unsigned int total,size_t bytes,void *payload){TMCGitService *s=(__bridge TMCGitService *)payload;NSTimeInterval now=NSDate.timeIntervalSinceReferenceDate;if(s.progress&&(now-s.lastProgress>.1||current==total)){s.lastProgress=now;s.progress([NSString stringWithFormat:@"推送对象 %u / %u",current,total],total?(double)current/total:0);}return s.cancelled?GIT_EUSER:0;}

static int PushResult(const char *ref,const char *status,void *payload){if(status)((TMCGitService *)(__bridge id)payload).pushRejection=[NSString stringWithFormat:@"%@：%@",S(ref),S(status)];return 0;}
static int CheckoutNotify(git_checkout_notify_t why,const char *path,const git_diff_file *base,const git_diff_file *target,const git_diff_file *workdir,void *payload){return ((TMCGitService *)(__bridge id)payload).cancelled?GIT_EUSER:0;}
static void CheckoutProgress(const char *path,size_t current,size_t total,void *payload){TMCGitService *s=(__bridge TMCGitService *)payload;NSTimeInterval now=NSDate.timeIntervalSinceReferenceDate;if(s.progress&&(now-s.lastProgress>.1||current==total)){s.lastProgress=now;s.progress([NSString stringWithFormat:@"写入文件 %zu / %zu",current,total],total?(double)current/total:0);}}
static git_remote_callbacks Callbacks(TMCGitService *service){git_remote_callbacks c=GIT_REMOTE_CALLBACKS_INIT;c.credentials=Credentials;c.transfer_progress=Transfer;c.sideband_progress=Sideband;c.push_transfer_progress=PushTransfer;c.push_update_reference=PushResult;c.payload=(__bridge void *)service;return c;}
